      {
        id: `product-${productSlug ?? 'unknown'}`,
        href: productSlug
          ? getPlatformProductHref(productSlug)
          : catalogBreadcrumbItem.href,
        label: 'Товар',
      },
    ];
  }

  const productCategorySlug = getLastCategorySlugFromProduct(product);

  return [
