import { type FormEvent, useEffect, useMemo, useState } from 'react';
import { useQuery } from '@tanstack/react-query';

import {
  FormImageFilesField,
  FormInputField,
  FormSelectField,
  FormTextareaField,
} from '@/components/ui/FormField';
import { Button } from '@/components/ui/Button';
import type { Ad, CreateAdPayload } from '@/entities/ad';
import { getCurrentUser } from '@/entities/auth';
import { getAdCategories } from '@/entities/ad-category';

type AdFormProps = {
  initialAd?: Ad;
  isPending?: boolean;
  submitLabel: string;
  onUploadImage: (file: File) => Promise<string>;
  onSubmit: (payload: CreateAdPayload) => void | Promise<void>;
  onCancel?: () => void;
};

export function AdForm({
  initialAd,
  isPending = false,
  submitLabel,
  onUploadImage,
  onSubmit,
  onCancel,
}: AdFormProps) {
  const { data: categories = [] } = useQuery({
    queryKey: ['ad-categories'],
    queryFn: getAdCategories,
  });

  const { data: currentUser } = useQuery({
    queryKey: ['current-user'],
    queryFn: getCurrentUser,
    staleTime: 5 * 60 * 1000,
  });

  const [title, setTitle] = useState(initialAd?.title ?? '');
  const [categoryId, setCategoryId] = useState(initialAd?.categoryId ?? '');
  const [price, setPrice] = useState(String(initialAd?.price ?? ''));
  const [description, setDescription] = useState(initialAd?.description ?? '');
  const [existingImageUrls, setExistingImageUrls] = useState<string[]>(
    initialAd?.images.map((image) => image.url) ?? [],
  );
  const [imageFiles, setImageFiles] = useState<File[]>([]);
  const [isUploadingImages, setIsUploadingImages] = useState(false);
  const [error, setError] = useState<string>();

  const [contactPhone, setContactPhone] = useState(
    initialAd?.contactPhone ?? '',
  );
  const [contactTelegram, setContactTelegram] = useState(
    initialAd?.contactTelegram ?? '',
  );
  const [contactEmail, setContactEmail] = useState(
    initialAd?.contactEmail ?? '',
  );
  const [contactOther, setContactOther] = useState(
    initialAd?.contactOther ?? '',
  );

  useEffect(() => {
    if (!initialAd && currentUser) {
      if (currentUser.phone && !contactPhone) {
        setContactPhone(currentUser.phone);
      }
      if (currentUser.email && !contactEmail) {
        setContactEmail(currentUser.email);
      }
    }
  }, [currentUser]);

  const categoryOptions = useMemo(
    () => [
      { value: '', label: 'Выберите категорию', disabled: true },
      ...categories.map((category) => ({
        value: category.id,
        label: category.name,
      })),
    ],
    [categories],
  );

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(undefined);

    if (!title.trim()) {
      setError('Укажите заголовок объявления.');
      return;
    }

    if (!categoryId) {
      setError('Выберите категорию объявления.');
      return;
    }

    const hasContact =
      contactPhone.trim() ||
      contactTelegram.trim() ||
      contactEmail.trim() ||
      contactOther.trim();

    if (!hasContact) {
      setError('Укажите хотя бы один способ связи.');
      return;
    }

    setIsUploadingImages(true);

    try {
      const uploadedImageUrls = await Promise.all(
        imageFiles.map(onUploadImage),
      );

      await onSubmit({
        title: title.trim(),
        description: description.trim(),
        categoryId,
        price: Number(price) || 0,
        imageUrls: [...existingImageUrls, ...uploadedImageUrls],
        contactPhone: contactPhone.trim() || undefined,
        contactTelegram: contactTelegram.trim() || undefined,
        contactEmail: contactEmail.trim() || undefined,
        contactOther: contactOther.trim() || undefined,
      });
    } catch (submitError) {
      setError(
        submitError instanceof Error
          ? submitError.message
          : 'Не удалось сохранить объявление.',
      );
    } finally {
      setIsUploadingImages(false);
    }
  }

  const isFormPending = isPending || isUploadingImages;

  return (
    <form className="flex flex-col gap-5" onSubmit={handleSubmit}>
      <FormInputField
        required
        label="Заголовок"
        value={title}
        onChange={(event) => setTitle(event.target.value)}
      />

      <FormSelectField
        required
        label="Категория"
        value={categoryId}
        options={categoryOptions}
        onValueChange={setCategoryId}
      />

      <FormInputField
        required
        type="number"
        label="Цена, ₽"
        value={price}
        onChange={(event) => setPrice(event.target.value)}
      />

      <FormTextareaField
        label="Описание"
        value={description}
        onChange={(event) => setDescription(event.target.value)}
      />

      <FormImageFilesField
        label="Изображения"
        caption="Можно выбрать несколько файлов. Новые файлы будут загружены при сохранении."
        files={imageFiles}
        existingImageUrls={existingImageUrls}
        disabled={isFormPending}
        onFilesChange={setImageFiles}
        onExistingImageUrlsChange={setExistingImageUrls}
      />

      <div className="flex flex-col">
        <span className="mb-2 ml-0.5 text-sm font-medium">Контакты</span>

        <div className="flex flex-col gap-4 rounded-2xl border border-border bg-card p-5">
          <FormInputField
            label="Телефон"
            type="tel"
            value={contactPhone}
            onChange={(event) => setContactPhone(event.target.value)}
          />

          <FormInputField
            label="Telegram"
            placeholder="@username"
            value={contactTelegram}
            onChange={(event) => setContactTelegram(event.target.value)}
          />

          <FormInputField
            label="Email"
            type="email"
            value={contactEmail}
            onChange={(event) => setContactEmail(event.target.value)}
          />

          <FormInputField
            label="Другой способ связи"
            placeholder="WhatsApp, ВКонтакте и т.д."
            value={contactOther}
            onChange={(event) => setContactOther(event.target.value)}
          />
        </div>

        <p className="mt-1 ml-0.5 text-xs leading-5 text-muted-foreground">
          Укажите хотя бы один способ связи. Незаполненные поля не будут показаны покупателям.
        </p>
      </div>

      {error && (
        <div className="rounded-xl border border-destructive/20 bg-destructive/5 p-3 text-sm text-destructive">
          {error}
        </div>
      )}

      <div className="flex flex-wrap gap-3">
        <Button type="submit" disabled={isFormPending}>
          {isUploadingImages ? 'Загружаем изображения...' : isPending ? 'Сохраняем...' : submitLabel}
        </Button>

        {onCancel && (
          <Button
            type="button"
            variant="outline"
            disabled={isFormPending}
            onClick={onCancel}
          >
            Отмена
          </Button>
        )}
      </div>
    </form>
  );
}
import { useEffect, useState } from 'react';

import { Button } from '@/components/ui/Button';
import { FormInputField } from '@/components/ui/FormField';
import { Modal } from '@/components/ui/Modal';
import type { User } from '@/entities/user';

type ProfileEditModalProps = {
  user: User;
  isOpen: boolean;
  isPending: boolean;
  error?: Error | null;
  onClose: () => void;
  onSubmit: (value: {
    nickname: string;
    firstName: string;
    lastName: string;
    patronymic: string;
    phone?: string;
  }) => void;
};

function getInputChangeHandler(
  setter: (value: string) => void,
) {
  return (event: React.ChangeEvent<HTMLInputElement>) => {
    setter(event.target.value);
  };
}

export function ProfileEditModal({
  user,
  isOpen,
  isPending,
  error,
  onClose,
  onSubmit,
}: ProfileEditModalProps) {
  const [nickname, setNickname] = useState(user.nickname);
  const [firstName, setFirstName] = useState(user.firstName ?? '');
  const [lastName, setLastName] = useState(user.lastName ?? '');
  const [patronymic, setPatronymic] = useState(user.patronymic ?? '');
  const [phone, setPhone] = useState(user.phone ?? '');

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    setNickname(user.nickname);
    setFirstName(user.firstName ?? '');
    setLastName(user.lastName ?? '');
    setPatronymic(user.patronymic ?? '');
    setPhone(user.phone ?? '');
  }, [isOpen, user]);

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    onSubmit({
      nickname: nickname.trim(),
      firstName: firstName.trim(),
      lastName: lastName.trim(),
      patronymic: patronymic.trim(),
      phone: phone.trim() || undefined,
    });
  }

  return (
    <Modal
      isOpen={isOpen}
      title="Редактировать профиль"
      size="md"
      onClose={onClose}
    >
      <form
        onSubmit={handleSubmit}
        className="flex max-h-full min-h-0 flex-1 flex-col overflow-hidden"
      >
        <div className="min-h-0 flex-1 space-y-6 overflow-y-auto p-6">
          <FormInputField
            required
            label="Имя аккаунта"
            value={nickname}
            onChange={getInputChangeHandler(setNickname)}
          />

          <FormInputField
            label="Фамилия"
            value={lastName}
            onChange={getInputChangeHandler(setLastName)}
          />

          <FormInputField
            label="Имя"
            value={firstName}
            onChange={getInputChangeHandler(setFirstName)}
          />

          <FormInputField
            label="Отчество"
            value={patronymic}
            onChange={getInputChangeHandler(setPatronymic)}
          />

          <FormInputField
            type="tel"
            label="Телефон"
            value={phone}
            onChange={getInputChangeHandler(setPhone)}
          />
        </div>

        <div className="flex flex-col gap-3 border-t border-border p-6">
          {error && (
            <p className="text-sm text-destructive">
              Не удалось сохранить. Проверьте соединение и попробуйте снова.
            </p>
          )}

          <div className="flex justify-end gap-3">
            <Button type="button" variant="outline" onClick={onClose}>
              Отмена
            </Button>
            <Button type="submit" disabled={isPending}>
              {isPending ? 'Сохраняем...' : 'Сохранить'}
            </Button>
          </div>
        </div>
      </form>
    </Modal>
  );
}
import { useEffect, useState } from 'react';
import { Pencil, Trash2 } from 'lucide-react';

import { Button } from '@/components/ui/Button';
import { Avatar } from '@/components/ui/Avatar';
import { Modal } from '@/components/ui/Modal';
import type { User } from '@/entities/user';

type AvatarEditModalProps = {
  user: User;
  isOpen: boolean;
  isPending: boolean;
  error?: Error | null;
  onClose: () => void;
  onSubmit: (value: { avatarFile?: File; remove: boolean }) => void;
};

export function AvatarEditModal({
  user,
  isOpen,
  isPending,
  error,
  onClose,
  onSubmit,
}: AvatarEditModalProps) {
  const [avatarFile, setAvatarFile] = useState<File | undefined>();
  const [avatarPreview, setAvatarPreview] = useState<string | undefined>(
    user.avatar?.url,
  );
  const [isRemoved, setIsRemoved] = useState(false);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    setAvatarFile(undefined);
    setAvatarPreview(user.avatar?.url);
    setIsRemoved(false);
  }, [isOpen, user]);

  function handleAvatarChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    setAvatarFile(file);
    setAvatarPreview(URL.createObjectURL(file));
    setIsRemoved(false);
  }

  function handleRemove() {
    setAvatarFile(undefined);
    setAvatarPreview(undefined);
    setIsRemoved(true);
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    onSubmit({
      avatarFile,
      remove: isRemoved,
    });
  }

  const hasAvatar = Boolean(avatarPreview) && !isRemoved;

  return (
    <Modal
      isOpen={isOpen}
      title="Аватар профиля"
      size="sm"
      onClose={onClose}
    >
      <form
        onSubmit={handleSubmit}
        className="flex max-h-full min-h-0 flex-1 flex-col overflow-hidden"
      >
        <div className="min-h-0 flex-1 space-y-6 overflow-y-auto p-6">
          <div className="flex flex-col items-center gap-4">
            <Avatar src={avatarPreview} name={user.nickname} size="xl" />

            <div className="flex flex-wrap items-center justify-center gap-1">
              <label className="cursor-pointer">
                <input
                  type="file"
                  accept="image/*"
                  className="sr-only"
                  onChange={handleAvatarChange}
                />
                <Button
                  type="button"
                  variant="outline"
                  size="icon-sm"
                  title="Загрузить новый аватар"
                  aria-label="Загрузить новый аватар"
                  asChild
                >
                  <span>
                    <Pencil className="size-3.5" strokeWidth={1.5} />
                  </span>
                </Button>
              </label>

              {hasAvatar && (
                <Button
                  type="button"
                  variant="destructive"
                  size="icon-sm"
                  title="Удалить аватар"
                  aria-label="Удалить аватар"
                  onClick={handleRemove}
                >
                  <Trash2 className="size-3.5" strokeWidth={1.5} />
                </Button>
              )}
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-3 border-t border-border p-6">
          {error && (
            <p className="text-sm text-destructive">
              Не удалось обновить аватар. Проверьте соединение и попробуйте
              снова.
            </p>
          )}

          <div className="flex justify-end gap-3">
            <Button type="button" variant="outline" onClick={onClose}>
              Отмена
            </Button>
            <Button type="submit" disabled={isPending}>
              {isPending ? 'Сохраняем...' : 'Сохранить'}
            </Button>
          </div>
        </div>
      </form>
    </Modal>
  );
}
import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';

import { SectionHeader } from '@/components/ui/Section';
import { useAuthStore } from '@/entities/auth';
import { useCartStore } from '@/entities/cart';
import {
  createOrder,
  type CreateOrderPayload,
  type Order,
} from '@/entities/order';
import { useSessionStore } from '@/entities/session';

import { CheckoutCustomerForm } from './components/CheckoutCustomerForm';
import { CheckoutEmptyState } from './components/CheckoutEmptyState';
import { CheckoutOrderSummary } from './components/CheckoutOrderSummary';
import { CheckoutPaymentState } from './components/CheckoutPaymentState';
import { buildCreateOrderPayload } from './logic/build-create-order-payload';
import { initialCheckoutFormValue } from './logic/initial-checkout-form-value';
import { isCheckoutFormValid } from './logic/is-checkout-form-valid';

import type { CheckoutFormValue } from './types/checkout-form';

export function Checkout() {
  const [formValue, setFormValue] = useState<CheckoutFormValue>(
    initialCheckoutFormValue,
  );
  const [createdOrder, setCreatedOrder] = useState<Order>();

  const accessToken = useAuthStore((state) => state.accessToken);

  const items = useCartStore((state) => state.items);
  const clearCart = useCartStore((state) => state.clearCart);
  const totalAmount = useCartStore((state) => state.getTotalAmount());

  const guestSessionId = useSessionStore((state) => state.guestSessionId);

  const createOrderMutation = useMutation({
    mutationFn: (payload: CreateOrderPayload) => {
      return createOrder(payload, accessToken);
    },
    onSuccess: (order) => {
      clearCart();
      setCreatedOrder(order);
    },
  });

  if (createdOrder) {
    return <CheckoutPaymentState order={createdOrder} />;
  }

  if (!items.length) {
    return <CheckoutEmptyState />;
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    createOrderMutation.mutate(
      buildCreateOrderPayload({
        formValue,
        items,
        guestSessionId,
      }),
    );
  }

  return (
    <div className="space-y-8">
      <SectionHeader
        title="Оформление заказа"
        description="Заказ в Маркете можно оформить без регистрации. Заказы, созданные после входа, сохраняются в истории профиля. Онлайн-оплата и доставка пока находятся в разработке."
      />

      <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_380px]">
        <CheckoutCustomerForm
          value={formValue}
          isPending={createOrderMutation.isPending}
          isSubmitDisabled={!isCheckoutFormValid(formValue)}
          errorMessage={
            createOrderMutation.isError
              ? 'Не удалось оформить заказ. Проверьте данные и попробуйте ещё раз.'
              : undefined
          }
          onChange={setFormValue}
          onSubmit={handleSubmit}
        />

        <CheckoutOrderSummary items={items} totalAmount={totalAmount} />
      </div>
    </div>
  );
}
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { randomUUID } from 'node:crypto';

import type { YookassaPayment, YookassaWebhookPayload } from './types/yookassa.types';

@Injectable()
export class PaymentsService {
  private readonly baseUrl = 'https://api.yookassa.ru/v3';

  constructor(private readonly configService: ConfigService) {}

  private getAuthHeader(): string {
    const shopId = this.configService.get<string>('YOOKASSA_SHOP_ID');
    const secretKey = this.configService.get<string>('YOOKASSA_SECRET_KEY');

    if (!shopId || !secretKey) {
      throw new InternalServerErrorException(
        'YOOKASSA_SHOP_ID or YOOKASSA_SECRET_KEY is not configured',
      );
    }

    return `Basic ${Buffer.from(`${shopId}:${secretKey}`).toString('base64')}`;
  }

  async createPayment(params: {
    orderId: string;
    amountKopecks: number;
    description: string;
    returnUrl: string;
  }): Promise<YookassaPayment> {
    const amountRubles = (params.amountKopecks / 100).toFixed(2);

    const response = await fetch(`${this.baseUrl}/payments`, {
      method: 'POST',
      headers: {
        Authorization: this.getAuthHeader(),
        'Idempotence-Key': randomUUID(),
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        amount: {
          value: amountRubles,
          currency: 'RUB',
        },
        confirmation: {
          type: 'embedded',
        },
        description: params.description,
        metadata: {
          orderId: params.orderId,
        },
        capture: true,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new InternalServerErrorException(
        `YooKassa createPayment failed: ${error}`,
      );
    }

    return response.json() as Promise<YookassaPayment>;
  }

  async getPayment(paymentId: string): Promise<YookassaPayment> {
    const response = await fetch(`${this.baseUrl}/payments/${paymentId}`, {
      headers: {
        Authorization: this.getAuthHeader(),
      },
    });

    if (!response.ok) {
      const error = await response.text();
      throw new InternalServerErrorException(
        `YooKassa getPayment failed: ${error}`,
      );
    }

    return response.json() as Promise<YookassaPayment>;
  }

  parseWebhook(body: unknown): YookassaWebhookPayload {
    const payload = body as YookassaWebhookPayload;

    if (payload?.type !== 'notification' || !payload?.event || !payload?.object?.id) {
      throw new Error('Invalid webhook payload');
    }

    return payload;
  }
}
