import type { LegalDocument } from '@/shared/legal';

import { LegalDocumentMeta } from './LegalDocumentMeta';
import { LegalRevisionDate } from './LegalRevisionDate';
import { LegalTableOfContents } from './LegalTableOfContents';

export function LegalDocumentLayout({ document }: { document: LegalDocument }) {
  return (
    <article className="mx-auto max-w-4xl space-y-8">
      <LegalDocumentMeta title={document.title} description={document.description} />

      <header className="space-y-3 border-b border-border pb-6">
        <h1 className="text-3xl font-semibold tracking-tight sm:text-4xl">{document.title}</h1>
        <p className="max-w-3xl leading-7 text-muted-foreground">{document.description}</p>
        <LegalRevisionDate value={document.revisionDate} />
      </header>

      <LegalTableOfContents sections={document.sections} />

      <div className="space-y-9">
        {document.sections.map((section) => (
          <section key={section.id} id={section.id} className="scroll-mt-28 space-y-4">
            <h2 className="text-xl font-semibold sm:text-2xl">{section.title}</h2>
            {section.paragraphs?.map((paragraph) => (
              <p key={paragraph} className="leading-7 text-foreground/85">{paragraph}</p>
            ))}
            {section.items && (
              <ul className="list-disc space-y-2 pl-5 text-foreground/85 marker:text-muted-foreground">
                {section.items.map((item) => <li key={item} className="pl-1 leading-7">{item}</li>)}
              </ul>
            )}
          </section>
        ))}
      </div>
    </article>
  );
}

import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Button } from '@/components/ui/Button';

const storageKey = 'dna-essential-storage-notice';

export function CookieNotice() {
  const [isVisible, setIsVisible] = useState(() => {
    try { return window.localStorage.getItem(storageKey) !== 'acknowledged'; } catch { return true; }
  });

  if (!isVisible) return null;

  function acknowledge() {
    try { window.localStorage.setItem(storageKey, 'acknowledged'); } catch { /* Storage may be unavailable. */ }
    setIsVisible(false);
  }

  return (
    <aside className="fixed inset-x-3 bottom-20 z-50 mx-auto max-w-3xl rounded-2xl border border-border bg-card p-4 shadow-xl md:bottom-4" aria-label="Уведомление о локальном хранении">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <p className="text-sm leading-6 text-muted-foreground">DNA использует только необходимое локальное хранение браузера для входа, корзины и избранного. Подробнее — в <Link className="font-medium text-foreground underline underline-offset-2" to="/cookie-policy">политике использования cookie и локального хранения</Link>.</p>
        <Button type="button" className="shrink-0" onClick={acknowledge}>Понятно</Button>
      </div>
    </aside>
  );
}

export function LegalRevisionDate({ value }: { value: string }) {
  return <p className="text-sm text-muted-foreground">Редакция от {value}</p>;
}

import { Link } from 'react-router-dom';

type LegalFormNoticeProps = {
  kind?: 'personal-data' | 'order' | 'publication';
};

const linkClassName = 'font-medium text-foreground underline underline-offset-2';

export function LegalFormNotice({ kind = 'personal-data' }: LegalFormNoticeProps) {
  if (kind === 'order') {
    return <p className="text-xs leading-5 text-muted-foreground">Нажимая «Оплатить заказ», пользователь принимает условия <Link className={linkClassName} to="/public-offer">Публичной оферты</Link> и подтверждает ознакомление с <Link className={linkClassName} to="/returns">Правилами возврата</Link>.</p>;
  }

  if (kind === 'publication') {
    return <p className="text-xs leading-5 text-muted-foreground">Публикуя объявление, пользователь подтверждает <Link className={linkClassName} to="/personal-data-publication-consent">согласие на распространение выбранных публичных контактов</Link>.</p>;
  }

  return <p className="text-xs leading-5 text-muted-foreground">Нажимая «Продолжить», пользователь даёт <Link className={linkClassName} to="/personal-data-consent">согласие на обработку персональных данных</Link> и подтверждает ознакомление с <Link className={linkClassName} to="/privacy-policy">Политикой обработки персональных данных</Link>.</p>;
}

import { Navigate, useLocation } from 'react-router-dom';

import { legalDocumentsByPath } from '@/shared/legal';
import { LegalDocumentLayout } from './components/LegalDocumentLayout';

export function LegalDocumentPage() {
  const { pathname } = useLocation();
  const document = legalDocumentsByPath.get(pathname);

  if (!document) return <Navigate to="/" replace />;

  return <LegalDocumentLayout document={document} />;
}

import { useEffect } from 'react';

type LegalDocumentMetaProps = {
  title: string;
  description: string;
};

export function LegalDocumentMeta({ title, description }: LegalDocumentMetaProps) {
  useEffect(() => {
    const previousTitle = document.title;
    const meta = document.querySelector<HTMLMetaElement>('meta[name="description"]');
    const previousDescription = meta?.content;

    document.title = `${title} — DNA`;
    meta?.setAttribute('content', description);

    return () => {
      document.title = previousTitle;
      if (meta && previousDescription !== undefined) meta.content = previousDescription;
    };
  }, [description, title]);

  return null;
}

import type { LegalSection } from '@/shared/legal';

export function LegalTableOfContents({ sections }: { sections: LegalSection[] }) {
  if (sections.length < 5) return null;

  return (
    <nav aria-label="Оглавление" className="rounded-2xl border border-border bg-muted/40 p-5">
      <h2 className="font-semibold">Оглавление</h2>
      <ol className="mt-3 grid gap-2 text-sm sm:grid-cols-2">
        {sections.map((section) => (
          <li key={section.id}>
            <a className="text-muted-foreground underline-offset-4 hover:text-foreground hover:underline" href={`#${section.id}`}>
              {section.title}
            </a>
          </li>
        ))}
      </ol>
    </nav>
  );
}

