import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';

import { useMutation } from '@tanstack/react-query';

import { Button } from '@/components/ui/Button';
import { LegalFormNotice } from '@/shared/legal/LegalFormNotice';
import { useAuthStore } from '@/entities/auth';
import { initiatePayment, type Order } from '@/entities/order';
import { formatPrice } from '@/shared/utils/format-price';

declare global {
  interface Window {
    YooMoneyCheckoutWidget: new (options: {
      confirmation_token: string;
      return_url: string;
      error_callback: (error: unknown) => void;
    }) => {
      render: (elementId: string) => void;
      destroy: () => void;
    };
  }
}

type CheckoutPaymentStateProps = {
  order: Order;
};

type PaymentStage = 'idle' | 'loading' | 'widget' | 'error';

export function CheckoutPaymentState({ order }: CheckoutPaymentStateProps) {
  const [stage, setStage] = useState<PaymentStage>('idle');
  const [errorMessage, setErrorMessage] = useState<string>();
  const widgetRef = useRef<{ destroy: () => void } | null>(null);
  const accessToken = useAuthStore((state) => state.accessToken);

  const initiateMutation = useMutation({
    mutationFn: () => initiatePayment(order.id, accessToken ?? undefined),
    onSuccess: (data) => {
      if (!data.confirmationToken) {
        setErrorMessage('Онлайн-оплата пока недоступна. Попробуйте позже.');
        setStage('error');
        return;
      }

      loadWidget(data.confirmationToken);
    },
    onError: () => {
      setErrorMessage('Онлайн-оплата пока недоступна. Попробуйте позже.');
      setStage('error');
    },
  });

  function loadWidget(confirmationToken: string) {
    setStage('loading');

    const scriptId = 'yookassa-checkout-js';

    function mountWidget() {
      const widget = new window.YooMoneyCheckoutWidget({
        confirmation_token: confirmationToken,
        return_url: `${window.location.origin}/checkout/result?orderId=${order.id}`,
        error_callback: () => {
          setErrorMessage('Не удалось открыть форму оплаты. Попробуйте позже.');
          setStage('error');
        },
      });

      widget.render('yookassa-widget-container');
      widgetRef.current = widget;
      setStage('widget');
    }

    if (document.getElementById(scriptId)) {
      mountWidget();
      return;
    }

    const script = document.createElement('script');
    script.id = scriptId;
    script.src = 'https://yookassa.ru/checkout-widget/v1/checkout-widget.js';
    script.onload = mountWidget;
    script.onerror = () => {
      setErrorMessage('Не удалось открыть форму оплаты. Попробуйте позже.');
      setStage('error');
    };
    document.head.appendChild(script);
  }

  useEffect(() => {
    return () => {
      widgetRef.current?.destroy();
    };
  }, []);

  return (
    <section className="mx-auto max-w-2xl space-y-6 rounded-2xl border border-border bg-card p-8">
      <div className="space-y-2">
        <p className="text-sm font-medium text-muted-foreground">
          Заказ создан
        </p>

        <h1 className="text-2xl font-semibold">Заказ ожидает оплаты</h1>

        <p className="text-sm text-muted-foreground">
          Номер заказа: <span className="text-foreground">{order.id}</span>
        </p>
      </div>

      <table className="w-full text-sm">
        <tbody>
          <tr className="border-b border-border">
            <td className="py-3 text-muted-foreground">Сумма к оплате</td>
            <td className="py-3 text-right text-lg font-semibold">
              {formatPrice(order.totalAmount)}
            </td>
          </tr>
          <tr>
            <td className="py-3 text-muted-foreground">Статус</td>
            <td className="py-3 text-right font-medium">Ожидает оплаты</td>
          </tr>
        </tbody>
      </table>

      {stage === 'error' && errorMessage && (
        <p className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">
          {errorMessage}
        </p>
      )}

      {stage === 'widget' && (
        <div id="yookassa-widget-container" className="min-h-[300px]" />
        <LegalFormNotice kind="order" />
      )}

      {stage !== 'widget' && (
        <p className="text-sm text-muted-foreground">
          Онлайн-оплата пока находится в разработке и может быть недоступна.
          Сохраните номер заказа, чтобы уточнить его статус.
        </p>
      )}

      {stage !== 'widget' && (
        <div className="flex flex-col gap-2 sm:flex-row">
          <Button
            onClick={() => initiateMutation.mutate()}
            disabled={initiateMutation.isPending || stage === 'loading'}
          >
            {initiateMutation.isPending || stage === 'loading'
              ? 'Открываем оплату...'
              : 'Проверить доступность оплаты'}
          </Button>

          <Button asChild variant="outline">
            <Link to="/market/catalog">Вернуться в каталог</Link>
          </Button>
        </div>
      )}
    </section>
  );
}
import { useEffect } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { CheckCircle, XCircle, Clock } from 'lucide-react';

import { useCartStore } from '@/entities/cart';
import { useAuthStore } from '@/entities/auth';
import { Button } from '@/components/ui/Button';

type ResultStatus = 'success' | 'pending' | 'failed';

function getStatus(params: URLSearchParams): ResultStatus {
  const status = params.get('status');

  if (status === 'succeeded' || status === 'success') return 'success';
  if (status === 'canceled' || status === 'failed' || status === 'cancelled') return 'failed';

  return 'pending';
}

const statusConfig: Record<
  ResultStatus,
  { icon: typeof CheckCircle; color: string; title: string; description: string }
> = {
  success: {
    icon: CheckCircle,
    color: 'text-green-500',
    title: 'Оплата прошла успешно',
    description: 'Платёж принят. Сохраните номер заказа для дальнейшего уточнения статуса.',
  },
  pending: {
    icon: Clock,
    color: 'text-yellow-500',
    title: 'Платёж обрабатывается',
    description:
      'Подтверждение платежа ещё не получено. Онлайн-оплата пока находится в разработке.',
  },
  failed: {
    icon: XCircle,
    color: 'text-destructive',
    title: 'Оплата не прошла',
    description:
      'Не удалось провести платёж. Онлайн-оплата пока находится в разработке.',
  },
};

export function CheckoutResultPage() {
  const [searchParams] = useSearchParams();
  const status = getStatus(searchParams);
  const orderId = searchParams.get('orderId');
  const config = statusConfig[status];
  const Icon = config.icon;

  const clearCart = useCartStore((state) => state.clearCart);
  const accessToken = useAuthStore((state) => state.accessToken);

  useEffect(() => {
    if (status === 'success') {
      clearCart();
    }
  }, [status, clearCart]);

  return (
    <div className="flex min-h-[60vh] items-center justify-center">
      <div className="mx-auto max-w-md space-y-6 text-center">
        <Icon className={`mx-auto size-16 ${config.color}`} />

        <div className="space-y-2">
          <h1 className="text-2xl font-semibold">{config.title}</h1>
          <p className="text-sm text-muted-foreground">{config.description}</p>
          {orderId && (
            <p className="text-sm text-muted-foreground">
              Номер заказа: <span className="font-medium text-foreground">{orderId}</span>
            </p>
          )}
        </div>

        <div className="flex flex-col gap-3 sm:flex-row sm:justify-center">
          {status === 'failed' ? (
            <Button asChild>
              <Link to="/checkout">Вернуться к оформлению</Link>
            </Button>
          ) : accessToken ? (
            <Button asChild>
              <Link to="/profile">Мои заказы</Link>
            </Button>
          ) : (
            <Button asChild>
              <Link to="/market/catalog">Вернуться в каталог</Link>
            </Button>
          )}

          <Button asChild variant="outline">
            <Link to="/">На главную</Link>
          </Button>
        </div>
      </div>
    </div>
  );
}
import type { OrderCustomer } from './order-customer';
import type { OrderItem } from './order-item';
import type { OrderStatus } from './order-status';

export type Order = OrderCustomer & {
  id: string;
  userId?: string;
  guestSessionId?: string;
  status: OrderStatus;
  items: OrderItem[];
  totalAmount: number;
  createdAt: string;
  updatedAt: string;
};export type OrderCustomer = {
  customerName: string;
  customerPhone: string;
  customerEmail?: string;
  deliveryAddress: string;
  comment?: string;
};import {
  BadgePercent,
  Network,
  PackagePlus,
} from 'lucide-react';

import type { ReferralEarningCategory } from '../types/referral-earning-category';

export const referralEarningCategories: ReferralEarningCategory[] = [
  {
    id: 'personal-cashback',
    title: 'Личный кешбэк',
    shortTitle: 'Кешбэк',
    description: 'Механика кешбэка пока находится в разработке.',
    icon: BadgePercent,
    details: {
      title: 'Личный кешбэк',
      paragraphs: [
